import {glassSource} from './glassfx.js';
import {safe} from '../app/utils.js';
export const FX_TYPES=['liquid-glass','particle-trail','interactive-type'];
export function webSource(state){const o={type:FX_TYPES.includes(state.type)?state.type:FX_TYPES[0],radius:Math.max(20,Math.min(200,Number(state.radius)||90)),strength:Math.max(0,Math.min(2,Number.isFinite(Number(state.strength))?Number(state.strength):.7)),smoothing:Math.max(.02,Math.min(.4,Number(state.smoothing)||.12)),density:Math.max(12,Math.min(160,Number(state.density)||70)),color:/^#[0-9a-f]{6}$/i.test(state.color)?state.color:'#bd5576',text:String(state.text||'UNEXPECTED').slice(0,40)};
 const config=JSON.stringify(o).replace(/</g,'\\u003c');
 const glass=o.type==='liquid-glass'?glassSource(o):null;
 const license=`<!-- MIT License — Copyright (c) 2026 SEKRET. Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the Software), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies, and to permit persons to whom the Software is furnished to do so, subject to including this copyright notice and permission notice in all copies or substantial portions. THE SOFTWARE IS PROVIDED AS IS, WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN CONTRACT, TORT OR OTHERWISE, ARISING FROM THE SOFTWARE OR ITS USE. Integration: no dependencies; use the section, scoped CSS and script together. -->`;if(glass)return glass.replace('<meta charset',license+'<meta charset');
 return `<!doctype html>
<!-- SEKRET WEB FX. Copyright (c) 2026 SEKRET. MIT License.
Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:
The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.
THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.
No dependencies. Place the section and style in your page; run the script after the section.
The demo background can be replaced with your content. Keep the sek-fx element and its data attributes. -->
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SEKRET / ${safe(o.type)}</title>
<style>
body{margin:0;background:#09090c}.sek-fx{position:relative;isolation:isolate;overflow:hidden;min-height:500px;height:100vh;display:grid;place-items:center;color:#f5eee9;background:radial-gradient(ellipse at 70% 20%,#511b32,transparent 55%),repeating-linear-gradient(115deg,#ffffff06 0 1px,transparent 1px 32px),#09090c;touch-action:pan-y}.sek-fx .sek-caption{position:absolute;top:6%;left:6%;font:11px monospace;letter-spacing:.14em}.sek-fx .sek-title{font:900 clamp(38px,10vw,150px)/.9 Arial,sans-serif;letter-spacing:-.065em;max-width:94%;text-align:center;overflow-wrap:anywhere;z-index:1}.sek-fx .sek-title span{display:inline-block;will-change:transform}.sek-fx canvas{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:2}.sek-fx .sek-lens{position:absolute;width:${o.radius*2}px;height:${o.radius*2}px;left:0;top:0;border-radius:45% 55% 58% 42%;pointer-events:none;z-index:3;border:1px solid #ffffff66;backdrop-filter:blur(${2+o.strength*7}px) saturate(1.7) contrast(1.12);background:linear-gradient(125deg,#ffffff40,transparent 35%,#ffffff08 65%,#ffffff35);box-shadow:inset 3px 3px 10px #fff5,inset -8px -10px 18px #0005,0 15px 50px #0004;mix-blend-mode:screen;opacity:0}.sek-fx .sek-note{position:absolute;bottom:6%;left:6%;right:6%;font:10px monospace;letter-spacing:.12em;display:flex;justify-content:space-between}
@media(prefers-reduced-motion:reduce){.sek-fx .sek-title span{will-change:auto}}
</style><section class="sek-fx"><div class="sek-caption">SEKRET / OPEN WEB STUDIES</div><div class="sek-title">${safe(o.text)}</div><canvas aria-hidden="true"></canvas><div class="sek-lens" aria-hidden="true"></div><div class="sek-note"><span>MOVE / TOUCH TO EXPLORE</span><span>${safe(o.type.toUpperCase())}</span></div></section>
<script>(()=>{'use strict';const config=${config},root=document.querySelector('.sek-fx'),canvas=root.querySelector('canvas'),ctx=canvas.getContext('2d'),lens=root.querySelector('.sek-lens'),title=root.querySelector('.sek-title'),reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;let width=1,height=1,active=false,x=0,y=0,tx=0,ty=0,last=0,raf=0,cursor=0;const dots=Array.from({length:config.density},()=>({x:0,y:0,vx:0,vy:0,life:0}));
if(config.type==='interactive-type'){title.textContent='';for(const char of config.text){const span=document.createElement('span');span.textContent=char===' '?String.fromCharCode(160):char;title.append(span);}}
const resize=()=>{const b=root.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);width=b.width;height=b.height;canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);};resize();
const move=e=>{const b=root.getBoundingClientRect();tx=e.clientX-b.left;ty=e.clientY-b.top;if(!active){x=tx;y=ty;}active=true;};const leave=()=>active=false;root.addEventListener('pointermove',move,{passive:true});root.addEventListener('pointerdown',move,{passive:true});root.addEventListener('pointerleave',leave);window.addEventListener('resize',resize);
function frame(now){const dt=Math.min(.05,(now-(last||now-16))/1000);last=now;if(!document.hidden){const k=reduced?1:1-Math.exp(-dt/(config.smoothing*2));const dx=tx-x,dy=ty-y;x+=dx*k;y+=dy*k;ctx.clearRect(0,0,width,height);
if(config.type==='liquid-glass'){lens.style.opacity=active?'1':'0';lens.style.transform='translate('+(x-config.radius)+'px,'+(y-config.radius)+'px) rotate('+(reduced?0:Math.max(-20,Math.min(20,dx*.3)))+'deg)';}
if(config.type==='particle-trail'){if(active&&!reduced){for(let i=0;i<Math.ceil(config.density*dt*1.5);i++){const d=dots[cursor++%dots.length],angle=cursor*2.39996;d.x=x;d.y=y;d.vx=Math.cos(angle)*config.strength*70+dx*2;d.vy=Math.sin(angle)*config.strength*70+dy*2;d.life=1;}}for(const d of dots){if(d.life<=0)continue;d.life-=dt*.65;d.vx*=Math.exp(-dt*1.8);d.vy*=Math.exp(-dt*1.8);d.x+=d.vx*dt;d.y+=d.vy*dt;ctx.globalAlpha=Math.max(0,d.life);ctx.fillStyle=config.color;ctx.beginPath();ctx.arc(d.x,d.y,Math.max(.2,d.life*config.radius*.035),0,7);ctx.fill();}ctx.globalAlpha=1;}
if(config.type==='interactive-type'){const b=root.getBoundingClientRect();for(const span of title.children){const r=span.getBoundingClientRect(),distance=Math.hypot(r.left+r.width/2-b.left-x,r.top+r.height/2-b.top-y),reach=active?Math.exp(-distance*distance/(config.radius*config.radius*4)):0;span.style.transform='translateY('+(-reach*config.strength*35)+'px) rotate('+(reduced?0:reach*config.strength*8)+'deg)';span.style.color=reach>.25?config.color:'';}}
}raf=requestAnimationFrame(frame);}raf=requestAnimationFrame(frame);window.addEventListener('pagehide',()=>{cancelAnimationFrame(raf);root.removeEventListener('pointermove',move);root.removeEventListener('pointerdown',move);root.removeEventListener('pointerleave',leave);window.removeEventListener('resize',resize);},{once:true});})();<\/script>`;
}

export function previewURL(state){const type=FX_TYPES.includes(state.type)?state.type:FX_TYPES[0];return '/assets/webfx/'+type+'.html?settings='+encodeURIComponent(JSON.stringify(state));}

